/*! `mtron` grammar compiled for Highlight.js 11.10.0 */
(function () {
    const regex = hljs.regex;
    var mtron_grammar = (function () {
        'use strict';

        /*
            Language: mtron
            Author: Marko A. Rodriguez (http://markorodriguez.com)
        */

        /** @type LanguageFn */
        function mtron(hljs) {
            const VAR = {};
            const MTRON_DOC_CALLOUT = {
                className: 'mtron-doc-callout',
                match: /(?<=\s)​[0-9]+​/,
                returnBegin: false,
                relevance: 10
            }
            const MTRON_FORM = {
                className: 'mtron-form',
                match: /\[|]|,|\{|}|\(|\)|(=>)|'|<|>|\/|\\|-|&|╲|╱/,
                returnBegin: false,
                relevance: 0
            }
            const MTRON_AUTO_FROM = {
                className: 'mtron-auto-from',
                match: /!\*/,
                returnBegin: false,
                relevance: 10
            }
            const MTRON_SUGAR_INST = {
                className: 'mtron-sugar-inst',
                match: /[@■|*_.]|(!)|(==)|(-->)|(->)|(<<)|(>>)|(\^)|(\?=)|(\?>)|(\?<)|(\?>=)/,
                returnBegin: false,
                relevance: 0
            }
            const MTRON_REC_KEY = {
                className: 'mtron-rec-key',
                begin: /[_a-zA-Z0-9:/]?[_a-zA-Z0-9:/]*\s*(?==>)/,
                returnBegin: false,
                relevance: 0
            }
            const MTRON_SINGLE_COMMENT = {
                className: 'mtron-comment',
                begin: /\[--.*(--])?/,
                returnBegin: false,
                relevance: 0
            }
            const MTRON_MULTI_COMMENT = {
                className: 'mtron-comment',
                begin: /\[==.*==]/,
                returnBegin: false,
                relevance: 0
            }
            const MTRON_PROMPT_BEGIN = {
                className: 'mtron-prompt-begin',
                begin: /mtron(?=>)/,
                returnBegin: false,
                relevance: 0
            }
            const MTRON_PROMPT_END = {
                className: 'mtron-prompt-end',
                begin: /(?<=(mtron))>/,
                returnBegin: false,
                relevance: 0
            }
            const MTRON_RESULT_PREFIX = {
                className: 'mtron-result-prefix',
                begin: /==+>/,
                returnBegin: false,
                relevance: 0
            }
            const MTRON_REC = {
                className: 'mtron-rec',
                begin: /=>/,
                returnBegin: false,
                relevance: 0
            }
            const MTRON_T = {
                className: 'mtron-T',
                begin: /(?<=::)T/,
                returnBegin: false,
                relevance: 10
            }
            const MTRON_TYPE = {
                className: 'mtron-type',
                begin: /([_a-zA-Z/]?[_a-zA-Z0-9/]+(?=\[))|((?<=[^a-zA-Z0-9])(bool|int|real|str|uri|rec|lst|code|inst|bytes|objs|rel|fail|A|B|C|D)(?=[^a-zA-Z0-9]))/,
                returnBegin: false,
                relevance: 0
            }
            const MTRON_TYPE_PREFIX = {
                className: 'mtron-type-prefix',
                begin: /[_a-zA-Z/{*+}:\-.0-9]+(?=::)/,
                returnBegin: false,
                relevance: 0
            }
            const MTRON_QUERY = {
                className: 'mtron-query',
                begin: /([a-zA-Z0-9]+=[^>])/,
                returnBegin: false,
                relevance: 0
            }
            const MTRON_DOM_RNG_QUERY = {
                className: 'mtron-dom-rng-query',
                begin: /(?<=[a-zA-Z0-9}\]])<=(?=[a-zA-Z0-9])/,
                returnBegin: false,
                relevance: 10
            }
            const MTRON_INST = {
                className: 'mtron-inst',
                begin: /([_a-z]*(?=\?))/,
                returnBegin: false,
                relevance: 0
            }
            const MTRON_AT_VID = {
                className: 'mtron-at-vid',
                begin: /@[_a-zA-Z/{*+,}:.\-0-9]+/,
                returnBegin: false,
                relevance: 0
            }
            /*const MTRON_URI = {
                className: 'mtron-uri',
                begin: /([/]+[:a-zA-Z0-9_#+/]+)|([/]*[:a-zA-Z0-9_#+]+(([:|/][:_a-zA-Z0-9_#+./]*([?][{}?<a-zA-Z0-9&_,=#.+/]*)?)|([?][{}?<a-zA-Z0-9&,=#.+/]*)))/,
                returnBegin: false,
                contains: [FORWARD_SLASH],
                relevance: 0
            }*/
            const MTRON_BOOL = {
                className: 'mtron-bool',
                begin: /true|false/,
                returnBegin: false,
                relevance: 0
            }
            const MTRON_NOOBJ = {
                className: 'mtron-noobj',
                begin: /noobj/,
                returnBegin: false,
                relevance: 10
            }
            const MTRON_LOG_INFO = {
                className: 'mtron-log-info',
                match: /\[INFO]/,
            }
            const MTRON_LOG_ERROR = {
                className: 'mtron-log-error',
                match: /\[ERROR]/,
            }
            const MTRON_LOG_WARN = {
                className: 'mtron-log-warn',
                match: /\[WARN]/,
            }
            const MTRON_THROWN = {
                className: 'mtron-thrown',
                match: /thrown\sat\sinst/
            }
            const MTRON_KEYWORD = {
                className: 'mtron-keyword',
                begin:/[a-zA-Z0-9_]+(?=\()/,
                returnBegin: false,
                relevance: 0
            }
            const MTRON_REAL = {
                classname: 'mtron-real',
                begin:/[+-]?[0-9]+[.][0-9]+/,
                relevance: 0,
                returnBegin:false
            }
            const MTRON_INSTF_JVM = {
                className: 'mtron-inst-f-jvm',
                begin: /<j>/,
                returnBegin: false,
                relevance: 0
            }
            const MTRON_BYTES = {
                className: 'mtron-bytes',
                begin: /0x[0-9a-fA-F]+/,
                relevance: 0,
                returnBegin:false
            }
            const MTRON_INT = {
                className: 'mtron-int',
                begin: /(?<![a-zA-Z])[+-]?[0-9]+(?![a-zA-Z])/,
                relevance: 0,
                returnBegin:false
            }
            const MTRON_STR = {
                className: 'mtron-str',
                begin: /(".*")|('.*')/,
                relevance: 0,
                returnBegin:false
            }
            const MTRON_PIPE = {
                className: 'mtron-pipe',
                begin: /┌|├|┐|└|┘|│|┤|─|⋰|⋱|⮝|⮞|⮜|⮟/,
                relevance: 0,
                returnBegin: false
            }
            const MTRON_MATCH_FAIL = {
                className: 'mtron-match-fail',
                begin: /X=>/,
                relevance: 10,
                returnBegin: false
            }
            const MTRON_FAIL = {
                className: 'mtron-fail',
                begin: /fail::/,
                relevance: 10,
                returnBegin: false
            }
            const MTRON_FAIL_BAR = {
                className: 'mtron-fail-bar',
                begin: /-{3,}/,
                relevance: 0,
                returnBegin: false

            }
            const PHASESHIFT_STUDIO_HEADER = {
                className: 'phaseshift-studio-header',
                match: /(PhaseShift Studio Presents)/,
            }
            const DOCS_IF_ELSE_THEN_CASE_DO = {
                className: 'docs-if-else-then-case-do',
                begin: /\((if|else|else if|then|case|do)\)/
            }
            return {
                name: 'mtron',
                contains: [
                    MTRON_AUTO_FROM,
                    PHASESHIFT_STUDIO_HEADER,
                    MTRON_MATCH_FAIL,
                    MTRON_FAIL,
                    MTRON_FAIL_BAR,
                    MTRON_TYPE,
                    MTRON_AT_VID,
                    MTRON_T,
                    MTRON_TYPE_PREFIX,
                    MTRON_STR,
                    MTRON_BYTES,
                    MTRON_DOC_CALLOUT,
                    DOCS_IF_ELSE_THEN_CASE_DO,
                    MTRON_PROMPT_BEGIN,
                    MTRON_PROMPT_END,
                    MTRON_REC,
                    MTRON_DOM_RNG_QUERY,
                    MTRON_QUERY,
                    MTRON_RESULT_PREFIX,
                    MTRON_LOG_INFO,
                    MTRON_LOG_ERROR,
                    MTRON_LOG_WARN,
                    MTRON_THROWN,
                    MTRON_SINGLE_COMMENT,
                    MTRON_MULTI_COMMENT,
                    MTRON_BOOL,
                    MTRON_INT,
                    MTRON_REAL,
                    MTRON_REC_KEY,
                    MTRON_INST,
                    MTRON_NOOBJ,
                    MTRON_INSTF_JVM,
                    MTRON_SUGAR_INST,
                    MTRON_KEYWORD,
                    //MTRON_URI,
                    MTRON_FORM,
                    MTRON_PIPE
                ]
            };
        }

        return mtron;
    })();

    hljs.registerLanguage('mtron', mtron_grammar);
    hljs.addPlugin(new CopyButtonPlugin({
        hook: (code, el) => {
            lines = code.split("\n");
            const pred = (item) => (!item.startsWith("=") &&
                null == item.match(/^\[(INFO|ERROR|DEBUG|WARN|TRACE)]/) &&
                !item.trim().startsWith("thrown"));
            const func = (item) => item.replace("mtron>","").replaceAll(/-\([0-9]+\)/g,"")
            return lines = lines.filter(pred).map(func).join("\n");
        },
        callback: (code, el) => {
            console.log(code);
        },
    }));
    locales["en"] = ["copy","🦇","copied to clipboard"];
})();